mapper.select:
SELECT game_id AS "gameId", entity_id AS "entityId", resource_key AS "resourceKey", stage AS stage, initial_value AS "initialValue", max_value AS "maxValue", change_revision AS "changeRevision", updated_at AS "updatedAt" FROM public.entity_resource_stage_values WHERE game_id = #{gameId}
AND entity_id = #{entityId}
AND resource_key = #{resourceKey}
ORDER BY entity_id, resource_key, stage
